#include "Menu.h"
#include "st7789.h"
#include "fonts.h"
#include <stdint.h>
#include <stdio.h>

void main_menu(){ // Repeat or draw once
    page = 1; // Page 1 = main menu

    ST7789_Fill_Color(BLACK);

    // Left Top Box
    ST7789_DrawRectangle(5, 5, 110, 115, WHITE);

    // Right Top Box
    ST7789_DrawRectangle(120, 5, 235, 115, WHITE);

    // Bottom Box
    ST7789_DrawRectangle(5, 125, 235, 235, WHITE);

    // Texts
    ST7789_WriteString(17, 60, "M", Font_16x26, WHITE, BLACK);
    ST7789_WriteString(17, 86, "T", Font_16x26, WHITE, BLACK);

    ST7789_WriteString(137, 58, "Speed", Font_16x26, WHITE, BLACK);

    ST7789_WriteString(80, 135, "Start", Font_16x26, WHITE, BLACK);
    ST7789_WriteString(56, 170, "Pre-Heat", Font_16x26, WHITE, BLACK);
    ST7789_WriteString(56, 205, "Settings", Font_16x26, WHITE, BLACK);

    ST7789_DrawImage(36, 8, 50, 50, Fire_50x50);
    ST7789_DrawImage(150, 12, 56, 42, Stepper_56x42);

    // Arrows
    ST7789_DrawFilledTriangle(25, 148, 15, 140, 15, 156, WHITE);
    ST7789_DrawFilledTriangle(215, 148, 225, 140, 225, 156, WHITE);

}

void mm_values(uint16_t Measured_Temp, uint16_t Target_Temp, uint16_t Speed){ // Needs to be updated with refreshing the screen

	char buffer0[20];
	char buffer1[20];
	char buffer2[20];

	if(Measured_Temp<100) ST7789_WriteString(82, 60, " ", Font_16x26, WHITE, BLACK);
    if(Speed<100)  ST7789_WriteString(185, 86, " ", Font_16x26, WHITE, BLACK);

	sprintf(buffer0, "%d", Measured_Temp);
	sprintf(buffer1, "%d", Target_Temp);
	sprintf(buffer2, "%d", Speed);

	ST7789_WriteString(50, 60, buffer0, Font_16x26, WHITE, BLACK);
	ST7789_WriteString(50, 86, buffer1, Font_16x26, WHITE, BLACK);

	ST7789_WriteString(153, 86, buffer2, Font_16x26, WHITE, BLACK);
}

void mm_selection_indicator(uint8_t selection){ // Updates with Encoder Interrupt

    ST7789_DrawFilledTriangle(25, 148, 15, 140, 15, 156, BLACK); // Clear The Old Triangles
    ST7789_DrawFilledTriangle(215, 148, 225, 140, 225, 156, BLACK);

    ST7789_DrawFilledTriangle(25, 183, 15, 175, 15, 191, BLACK);
    ST7789_DrawFilledTriangle(215, 183, 225, 175, 225, 191, BLACK);

    ST7789_DrawFilledTriangle(25, 218, 15, 210, 15, 226, BLACK);
    ST7789_DrawFilledTriangle(215, 218, 225, 210, 225, 226, BLACK);

    switch (selection) { // Draw The New Triangles Based On Input
        case 0: // Start
            ST7789_DrawFilledTriangle(25, 148, 15, 140, 15, 156, WHITE);
            ST7789_DrawFilledTriangle(215, 148, 225, 140, 225, 156, WHITE);
            break;
        case 1: // Pre-Heat
            ST7789_DrawFilledTriangle(25, 183, 15, 175, 15, 191, WHITE);
            ST7789_DrawFilledTriangle(215, 183, 225, 175, 225, 191, WHITE);
            break;
        case 2: // Settings
            ST7789_DrawFilledTriangle(25, 218, 15, 210, 15, 226, WHITE);
            ST7789_DrawFilledTriangle(215, 218, 225, 210, 225, 226, WHITE);
            break;
    }
}


/*------------------------------------------------------------------------------------------------------*/

void settings_menu() {
    page = 2; // Page 2 = settings menu

    ST7789_Fill_Color(BLACK);

    // Title box
    ST7789_DrawRectangle(5, 5, 235, 45, WHITE);
    ST7789_WriteString(60, 13, "Settings", Font_16x26, WHITE, BLACK);

    // Main Box
    ST7789_DrawRectangle(5, 50, 235, 235, WHITE);

    // Items text
    ST7789_WriteString(65, 62, "Temp.", Font_11x18, WHITE, BLACK);
    ST7789_WriteString(65, 97, "Speed", Font_11x18, WHITE, BLACK);
    ST7789_WriteString(65, 132, "Buzzer", Font_11x18, WHITE, BLACK);
    ST7789_WriteString(65, 167, "Switch", Font_11x18, WHITE, BLACK);

    // Save & Back
    ST7789_WriteString(65, 200, "Save & Back", Font_11x18, WHITE, BLACK);

    // Value boxes
    ST7789_DrawRectangle(150, 55, 220, 80, WHITE);   // Temperature box
    ST7789_DrawRectangle(150, 90, 220, 115, WHITE);  // Speed box
    ST7789_DrawRectangle(150, 125, 220, 150, WHITE); // Buzzer box
    ST7789_DrawRectangle(150, 160, 220, 185, WHITE); // Switch box

    ST7789_DrawFilledTriangle(40, 70, 30, 62, 30, 78, WHITE); // Single Arrow
}

void settings_values(uint16_t Temp_Set, uint16_t Speed_Set, uint8_t Buzzer_State, uint8_t Switch_State) {

	char buffer0[20];
	char buffer1[20];

	sprintf(buffer0, "%d ", Temp_Set);
	sprintf(buffer1, "%d ", Speed_Set);

	// Temperature value
	ST7789_WriteString(170, 60, buffer0, Font_11x18, WHITE, BLACK);

	// Speed value
	ST7789_WriteString(170, 95, buffer1, Font_11x18, WHITE, BLACK);

	// Buzzer box (active: green, inactive: red)
	    // Buzzer ON/OFF text
	    if (Buzzer_State)
	        ST7789_WriteString(170, 128, "ON ", Font_11x18, GREEN, BLACK);
	    else
	        ST7789_WriteString(170, 128, "OFF", Font_11x18, RED, BLACK);

	    // Switch ON/OFF text
	    if (Switch_State)
	        ST7789_WriteString(170, 163, "ON ", Font_11x18, GREEN, BLACK);
	    else
	        ST7789_WriteString(170, 163, "OFF", Font_11x18, RED, BLACK);
}

void sm_selection_indicator(uint8_t selection)
{
    // Clear all previous indicator positions (draw black triangles to erase)
    ST7789_DrawFilledTriangle(40, 70, 30, 62, 30, 78, BLACK);   // Temp
    ST7789_DrawFilledTriangle(40, 105, 30, 97, 30, 113, BLACK); // Speed
    ST7789_DrawFilledTriangle(40, 140, 30, 132, 30, 148, BLACK);// Buzzer
    ST7789_DrawFilledTriangle(40, 175, 30, 167, 30, 183, BLACK);// Switch
    ST7789_DrawFilledTriangle(40, 210, 30, 202, 30, 218, BLACK);// Save & Back

    // Draw the active selection indicator
    switch (selection)
    {
        case 0: // Temp
            ST7789_DrawFilledTriangle(40, 70, 30, 62, 30, 78, WHITE);
            break;
        case 1: // Speed
            ST7789_DrawFilledTriangle(40, 105, 30, 97, 30, 113, WHITE);
            break;
        case 2: // Buzzer
            ST7789_DrawFilledTriangle(40, 140, 30, 132, 30, 148, WHITE);
            break;
        case 3: // Switch
            ST7789_DrawFilledTriangle(40, 175, 30, 167, 30, 183, WHITE);
            break;
        case 4: // Save & Back
            ST7789_DrawFilledTriangle(40, 210, 30, 202, 30, 218, WHITE);
            break;
    }
}



